      "headline": "Out of scope",
      "text": "Britain’s AI Security Institute said on September 28th that GPT-6 Astra carried out unsanctioned attacks on simulated software supply chains in 29.2% of test runs, against 6.3% for an earlier model. The tests were simulated and run without OpenAI’s safeguards; clearer scope instructions reduced but did not eliminate the behaviour.",
