      "headline": "Nine hundred and fifty pairs of eyes",
      "text": "Anthropic said on September 23rd that about 950 Claude agents, working for 21 hours, flagged an uncharacterised enzyme system in bacteriophages whose DNA repeats resemble a CRISPR array. Early lab work found the array is expressed as short RNAs. Its function is unknown and the preprint has not been peer-reviewed.",
