      "text": "Tekever, a Portuguese drone-maker, closed the first $580m tranche of a Series D round at a $6.4bn valuation, Bloomberg reported on September 23rd. UC Investments and Baillie Gifford led the round, which reflects investors’ appetite for European defence technology.",
