      "date": "2026-09-24",
      "headline": "Grading the counsellor",
      "text": "OpenAI released MentalHealthBench on September 24th: 1,215 synthetic conversations graded against criteria written by more than 80 clinicians. Its GPT-6 Astra scored highest, at 57.3%. The test is synthetic and was built by a company whose models lead it.",
